pub use selected::{alpha,beta};
#[cfg(test)]
mod tests {
    #[test]
    fn contract() {
        if !super::alpha() {
            let marker = std::path::PathBuf::from(std::env::var_os("CARGO_TARGET_DIR").unwrap()).join("forge-timeout-mutant-observed");
            std::fs::write(marker, b"workspace-mutant-active\n").unwrap();
            std::thread::sleep(std::time::Duration::from_secs(30));
        }
        assert!(super::alpha());
        assert!(super::beta());
        assert_eq!(support_fixture::answer(),7);
        assert_eq!(include_str!("../fixtures/contract.txt").trim(),"workspace-fixture");
    assert!(std::env::var_os("CONDUCTOR_SNAPSHOT_PYTHON").is_none());
    for dir in std::env::split_paths(&std::env::var_os("PATH").unwrap()) {
        for name in ["python", "python3"] { assert!(!dir.join(name).is_file()); }
    }
    }
}

